// Method 12 — the RSS feed.
//
// /rss.xml is generated by src/pages/rss.xml.ts and, unlike every other artifact, nothing
// else in the pipeline ever looks at it. A feed rots quietly: retitle a page, retire one,
// add one, and the feed keeps advertising the old shape until a reader follows a link into
// a 404. It also repeats each page's own <title> and <meta name="description"> — the two
// things most likely to move without anyone remembering the feed exists.
//
// So the invariant this check enforces is "the feed says exactly what the pages say, and
// says it about every page a crawler is invited to index", not "the feed is well-formed
// XML". Well-formedness is the easy half; agreement is the half that decays.
import fs from 'node:fs';
import path from 'node:path';
import { ROOT, fail, warn, pass, loadDist, classifyPage, attr, findAll, parseHtml, textOf } from '../_util.mjs';

export const id = 'feed';
export const name = 'RSS 变更订阅与站点一致';

const DIST_HOST = { 'dist-global': 'https://gficcrew.com', 'dist-cn': 'https://gficcrew.cn' };

/** Minimal reader for the feed this project writes: flat <channel> plus flat <item>s. */
function parseFeed(xml) {
  const unescape = (s) =>
    s
      .replace(/&lt;/g, '<')
      .replace(/&gt;/g, '>')
      .replace(/&quot;/g, '"')
      .replace(/&apos;/g, "'")
      .replace(/&amp;/g, '&'); // last: "&amp;lt;" is a literal "&lt;", not a "<"
  const tagIn = (block, name) => {
    const m = new RegExp(`<${name}(?:\\s[^>]*)?>([\\s\\S]*?)</${name}>`).exec(block);
    return m ? unescape(m[1].trim()) : null;
  };

  const firstItem = xml.indexOf('<item>');
  const channel = firstItem === -1 ? xml : xml.slice(0, firstItem);
  const items = [...xml.matchAll(/<item>([\s\S]*?)<\/item>/g)].map((m) => ({
    title: tagIn(m[1], 'title'),
    link: tagIn(m[1], 'link'),
    guid: tagIn(m[1], 'guid'),
    guidPermalink: /<guid[^>]*isPermaLink=["']true["']/i.test(m[1]),
    category: tagIn(m[1], 'category'),
    pubDate: tagIn(m[1], 'pubDate'),
    description: tagIn(m[1], 'description'),
  }));
  return { channel, items, lastBuildDate: tagIn(channel, 'lastBuildDate') };
}

/** The two head fields the feed is supposed to mirror. */
function headOf(html) {
  const tree = parseHtml(html);
  const title = textOf(findAll(tree, 'title')[0] || {});
  const metas = findAll(tree, 'meta');
  const d = metas.find((m) => (attr(m, 'name') || '') === 'description');
  return { title, description: d ? attr(d, 'content') || '' : '' };
}

export async function run() {
  const out = [];
  const dists = ['dist-global', 'dist-cn'].filter((d) => fs.existsSync(path.join(ROOT, d)));
  if (!dists.length) return [warn('没有可检查的产物', '先跑 npm run build')];

  for (const dist of dists) {
    const feedPath = path.join(ROOT, dist, 'rss.xml');
    if (!fs.existsSync(feedPath)) {
      out.push(fail(`${dist} 没有 rss.xml`));
      continue;
    }
    const { channel, items, lastBuildDate } = parseFeed(fs.readFileSync(feedPath, 'utf8'));

    const pages = loadDist(dist).map((p) => ({ ...p, ...classifyPage(p) }));
    const indexable = pages.filter((p) => p.kind === 'indexable');
    const byPath = new Map(indexable.map((p) => [p.urlPath, { ...headOf(p.html), urlPath: p.urlPath }]));

    const wrongHost = [];
    const dangling = [];
    const titleDrift = [];
    const descDrift = [];
    const badGuid = [];
    const badDate = [];
    const seen = new Map();

    for (const item of items) {
      const link = item.link || '';
      if (!link.startsWith(DIST_HOST[dist])) {
        wrongHost.push(`${link} 不属于 ${DIST_HOST[dist]}`);
        continue;
      }
      const urlPath = link.slice(DIST_HOST[dist].length) || '/';
      seen.set(urlPath, (seen.get(urlPath) || 0) + 1);

      const page = byPath.get(urlPath);
      if (!page) {
        dangling.push(`${urlPath}（该产物里没有这个可收录页面）`);
        continue;
      }
      if (item.title !== page.title) titleDrift.push(`${urlPath}\n      feed:「${item.title}」\n      page:「${page.title}」`);
      if (item.description !== page.description) {
        descDrift.push(`${urlPath}\n      feed:「${(item.description || '').slice(0, 90)}…」\n      page:「${page.description.slice(0, 90)}…」`);
      }
      if (!item.guidPermalink || item.guid !== link) badGuid.push(`${urlPath} guid=「${item.guid}」isPermaLink=${item.guidPermalink}`);

      if (!item.pubDate) {
        badDate.push(`${urlPath} 没有 pubDate`);
      } else {
        const t = Date.parse(item.pubDate);
        if (Number.isNaN(t)) badDate.push(`${urlPath} pubDate 无法解析：${item.pubDate}`);
        // A day of slack: a dirty file's mtime is "now" and the clock can disagree.
        else if (t > Date.now() + 86400000) badDate.push(`${urlPath} pubDate 在未来：${item.pubDate}`);
      }
    }

    const missing = indexable.map((p) => p.urlPath).filter((u) => !seen.has(u));
    const dupes = [...seen.entries()].filter(([, n]) => n > 1).map(([u, n]) => `${u} ×${n}`);

    // Newest first. An entry with no date sorts last, so it must not appear before a dated one.
    const undated = items.filter((i) => !i.pubDate).length;
    const dated = items.filter((i) => i.pubDate).map((i) => Date.parse(i.pubDate));
    const sorted = dated.every((t, i) => i === 0 || dated[i - 1] >= t);
    const orderOk = sorted && (undated === 0 || items.slice(-undated).every((i) => !i.pubDate));

    const newest = dated.length ? new Date(Math.max(...dated)).toUTCString() : null;
    const buildDateOk = !newest || lastBuildDate === newest;
    const selfLink = /<atom:link href="([^"]+)" rel="self"/.exec(channel);

    out.push(
      pass(
        `${dist} 订阅条目`,
        `${items.length} 条（可收录页 ${indexable.length} 个）｜最新 ${newest || '(无)'}`,
      ),
    );
    out.push(bucket(`${dist} feed 只指向本域名`, wrongHost));
    out.push(bucket(`${dist} feed 链接都指向真实页面`, dangling));
    out.push(bucket(`${dist} feed 标题与页面 <title> 逐字一致`, titleDrift));
    out.push(bucket(`${dist} feed 描述与页面 meta description 逐字一致`, descDrift));
    out.push(bucket(`${dist} feed 覆盖每个可收录页面`, missing));
    out.push(bucket(`${dist} feed 无重复条目`, dupes));
    out.push(bucket(`${dist} guid 是永久链接且等于 link`, badGuid));
    out.push(bucket(`${dist} pubDate 可解析且不在未来`, badDate));
    out.push(bucket(`${dist} 条目按 pubDate 由新到旧`, orderOk ? [] : ['排序不符']));
    out.push(bucket(`${dist} lastBuildDate 等于最新条目`, buildDateOk ? [] : ['与最新条目不一致']));
    out.push(
      bucket(
        `${dist} feed 声明 atom:link rel=self`,
        selfLink && selfLink[1] === `${DIST_HOST[dist]}/rss.xml` ? [] : [`self=${selfLink ? selfLink[1] : '(缺失)'}`],
      ),
    );
  }

  return out;
}

// --- helpers ---------------------------------------------------------------

const bucket = (label, items, level = 'fail') => {
  if (!items.length) return pass(label);
  const max = 10;
  const evidence = items.slice(0, max).concat(items.length > max ? [`…另有 ${items.length - max} 处`] : []);
  return (level === 'warn' ? warn : fail)(`${label}（${items.length} 处）`, '', evidence);
};
